{"content":"#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

#define SAMPLE_RATE 44100
#define DURATION_SEC 2
#define NUM_SAMPLES (SAMPLE_RATE * DURATION_SEC)
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define NUM_TONES 2
#define PI 3.14159265358979323846
#define SCALE_FACTOR 0.9

static const double FREQS[NUM_TONES] = {440.0, 880.0};
static const double AMPS[NUM_TONES] = {0.3, 0.2};

static void write_u16le(FILE *f, uint16_t v) {
    uint8_t b[2];
    b[0] = (uint8_t)(v & 0xFFu);
    b[1] = (uint8_t)((v >> 8) & 0xFFu);
    fwrite(b, 1, 2, f);
}

static void write_u32le(FILE *f, uint32_t v) {
    uint8_t b[4];
    b[0] = (uint8_t)(v & 0xFFu);
    b[1] = (uint8_t)((v >> 8) & 0xFFu);
    b[2] = (uint8_t)((v >> 16) & 0xFFu);
    b[3] = (uint8_t)((v >> 24) & 0xFFu);
    fwrite(b, 1, 4, f);
}

static void write_wav_header(FILE *f, uint32_t data_size) {
    uint32_t byte_rate = (uint32_t)(SAMPLE_RATE * NUM_CHANNELS * BITS_PER_SAMPLE / 8);
    uint16_t block_align = (uint16_t)(NUM_CHANNELS * BITS_PER_SAMPLE / 8);
    uint32_t file_size_minus_8 = 36u + data_size;

    fwrite("RIFF", 1, 4, f);
    write_u32le(f, file_size_minus_8);
    fwrite("WAVE", 1, 4, f);
    fwrite("fmt ", 1, 4, f);
    write_u32le(f, 16u);
    write_u16le(f, 1u);
    write_u16le(f, (uint16_t)NUM_CHANNELS);
    write_u32le(f, (uint32_t)SAMPLE_RATE);
    write_u32le(f, byte_rate);
    write_u16le(f, block_align);
    write_u16le(f, (uint16_t)BITS_PER_SAMPLE);
    fwrite("data", 1, 4, f);
    write_u32le(f, data_size);
}

static int16_t quantize_sample(double sample_float) {
    double v = sample_float * 32767.0 * SCALE_FACTOR;
    long s = (long)v;
    if (s > 32767L) {
        s = 32767L;
    } else if (s < -32768L) {
        s = -32768L;
    }
    return (int16_t)s;
}

static void generate_samples(int16_t *buffer, uint32_t count) {
    uint32_t i;
    int k;
    for (i = 0; i < count; i++) {
        double t = (double)i / (double)SAMPLE_RATE;
        double acc = 0.0;
        for (k = 0; k < NUM_TONES; k++) {
            acc += AMPS[k] * sin(2.0 * PI * FREQS[k] * t);
        }
        buffer[i] = quantize_sample(acc);
    }
}

int main(void) {
    static int16_t samples[NUM_SAMPLES];
    FILE *f = NULL;
    uint32_t i;
    uint32_t data_size = (uint32_t)NUM_SAMPLES * (uint32_t)(BITS_PER_SAMPLE / 8);

    generate_samples(samples, (uint32_t)NUM_SAMPLES);

    f = fopen("reconstructed.wav", "wb");
    if (f == NULL) {
        return 1;
    }

    write_wav_header(f, data_size);

    for (i = 0; i < (uint32_t)NUM_SAMPLES; i++) {
        write_u16le(f, (uint16_t)samples[i]);
    }

    fclose(f);
    return 0;
}
